CREATE VIEW dbo.IV_Q$INCENTIVO ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario,  DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao,  SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , PERC_INCENTIVO, NRO_COTACAO_ALCADA, BASE_CALCULO, TOTAL_BASE_ALCADA, MARCAR_ENTREGUE, MARCAR_VENDIDO, OUTROS_INCENTIVOS, NRO_COTACAO, BASE_OUTROS, CAMPANHA1, PERC_CMP1, CAMPANHA2, PERC_CMP2, CAMPANHA3, PERC_CMP3, CAMPANHA1JD, CMP_1JD, TOTAL_BRUTO, DATA_ENVIO_XML, NRO_NF, DATA_EMISSAO, TOTAL_LIQUIDO, COMPRAR_VENDIDO, NRO_NF_ALCADA, NRO_PROC_ALCADA, DTA_NF_ALCADA, TIPO_CAMPANHA_1, TIPO_CAMPANHA_2, TIPO_CAMPANHA_3, TIPO_CAMPANHA_DE_INC, NOME_CAMPANHA_DE_INC, TIPO_INCENTIVO_2, NOME_INCENTIVO_2, TIPO_INCENTIVO_3, NOME_INCENTIVO_3, TIPO_INCENTIVO_4, NOME_INCENTIVO_4, __CAMPANHA_4, _CAMPANHA1, _CAMPANHA2, _CAMPANHA3, _CAMPANHA4)     AS SELECT TBASE.SEQPESSOA, TBASE.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO,  QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS,  QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO,  QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.PERC_INCENTIVO, TABF.NRO_COTACAO_ALCADA, TABF.BASE_CALCULO, TABF.TOTAL_BASE_ALCADA, TABF.MARCAR_ENTREGUE, TABF.MARCAR_VENDIDO, TABF.OUTROS_INCENTIVOS, TABF.NRO_COTACAO, TABF.BASE_OUTROS, TABF.CAMPANHA1, TABF.PERC_CMP1, TABF.CAMPANHA2, TABF.PERC_CMP2, TABF.CAMPANHA3, TABF.PERC_CMP3, TABF.CAMPANHA1JD, TABF.CMP_1JD, TABF.TOTAL_BRUTO, TABF.DATA_ENVIO_XML, TABF.NRO_NF, TABF.DATA_EMISSAO, TABF.TOTAL_LIQUIDO, TABF.COMPRAR_VENDIDO, TABF.NRO_NF_ALCADA, TABF.NRO_PROC_ALCADA, TABF.DTA_NF_ALCADA, TABF.TIPO_CAMPANHA_1, TABF.TIPO_CAMPANHA_2, TABF.TIPO_CAMPANHA_3, TABF.TIPO_CAMPANHA_DE_INC, TABF.NOME_CAMPANHA_DE_INC, TABF.TIPO_INCENTIVO_2, TABF.NOME_INCENTIVO_2, TABF.TIPO_INCENTIVO_3, TABF.NOME_INCENTIVO_3, TABF.TIPO_INCENTIVO_4, TABF.NOME_INCENTIVO_4, TABF.__CAMPANHA_4, TABF._CAMPANHA1, TABF._CAMPANHA2, TABF._CAMPANHA3, TABF._CAMPANHA4    FROM IV_Q_INCENTIVO TABF  	JOIN IV_QUESTIONARIO QST ON QST.SEQQUESTIONARIO =  TABF.SEQQUESTIONARIO  	JOIN IV_FORMULARIO FRM ON   FRM.SEQFORMULARIO = QST.SEQFORMULARIO  	JOIN GE_PESSOA TBASE ON TBASE.SEQPESSOA = QST.SEQPESSOA 